<?php
declare(strict_types=1);
require_once __DIR__.'/../src/account_helpers.php';
require_once __DIR__.'/../src/audience_ai.php';
$checks=0;
$expect=static function(bool $ok,string $message)use(&$checks):void{if(!$ok)throw new RuntimeException($message);$checks++;};
$reject=static function(callable $call,string $message)use($expect):void{$failed=false;try{$call();}catch(Throwable){$failed=true;}$expect($failed,$message);};
$base=['request_id'=>'12345678-1234-4234-a234-123456789012','mode'=>'content','operation'=>'rewrite','text'=>'Hello *|FNAME|*, meet us in Jerusalem on Sunday.','tone'=>'warm'];
$request=audienceAiRequest($base,'editor');
$expect($request['role']==='editor'&&$request['_audience_ai']===1,'Server role and explicit purpose');
foreach(['reviewer','guest','']as$role)$reject(static fn()=>audienceAiRequest($base,$role),'Unprivileged writing is rejected');
foreach(['superadmin','admin','editor','reviewer']as$role){
    $analysisRequest=audienceAiRequest(array_replace($base,['mode'=>'analytics','operation'=>'analyze','role'=>'admin']),$role);
    $expect($analysisRequest['role']===$role&&$analysisRequest['mode']==='analytics','Every signed-in role can analyze using its server-authorized role');
}
foreach(['guest','', 'unknown']as$role)$reject(static fn()=>audienceAiRequest(array_replace($base,['mode'=>'analytics','operation'=>'analyze']),$role),'Unknown or unauthenticated roles cannot analyze');
$expect(!audienceAiCanAccess('reviewer','content')&&!audienceAiCanAccess('reviewer','settings'),'Analytics access does not grant writing or unsupported actions');
foreach([['operation'=>'send'],['tone'=>'invented'],['request_id'=>'../other'],['text'=>[]],['text'=>str_repeat('x',10001)],['prompt'=>str_repeat('x',1501)],['text'=>"bad\0text"],['mode'=>'settings']]as$bad)$reject(static fn()=>audienceAiRequest(array_replace($base,$bad),'admin'),'Malformed or oversized input is rejected');
$reply=['headline'=>'A warm invitation','text'=>'Hello *|FNAME|*, join us in Jerusalem on Sunday.','subjects'=>['A warm invitation','Join our community','A moment to connect'],'recommendations'=>['Check the event details before use.']];
$raw=static fn(array $v):array=>['done'=>true,'done_reason'=>'stop','message'=>['content'=>json_encode($v)]];
$decoded=audienceAiReply($raw($reply),$request);
$expect($decoded['purpose']==='audience-ai'&&$decoded['text']===$reply['text'],'Structured plain text is retained for review');
$reject(static fn()=>audienceAiReply($raw(array_replace($reply,['text'=>'<img src=x onerror=alert(1)>'])),$request),'Model HTML is rejected');
$reject(static fn()=>audienceAiReply($raw(array_replace($reply,['text'=>'Hello friend'])),$request),'A rewrite must preserve merge tags');
$reject(static fn()=>audienceAiReply(['done'=>false,'message'=>['content'=>json_encode($reply)]],$request),'Truncated inference is not a completed suggestion');
$reject(static fn()=>audienceAiReply(array_replace($raw($reply),['message'=>['content'=>json_encode($reply),'tool_calls'=>[['name'=>'send']]]]),$request),'No model tool calls');
$reject(static fn()=>audienceAiReply($raw(array_replace($reply,['subjects'=>['x'=>1]])),$request),'Wrong result shape is rejected');
$check=audienceAiChecks(str_repeat('word ',501),'A subject');$expect(count($check['findings'])===1&&$check['facts'][0]['value']===501,'Word count and long-newsletter check are deterministic');
$overview=['totals'=>['accepted'=>120,'delivery_rate'=>90,'open_rate'=>40,'click_rate'=>5,'bounce_rate'=>2,'unsubscribe_rate'=>1],'previous'=>['accepted'=>100,'delivery_rate'=>95,'open_rate'=>45,'click_rate'=>10,'bounce_rate'=>0,'unsubscribe_rate'=>null],'daily'=>['2026-10-16'=>['accepted'=>120,'clicks'=>6,'email'=>'secret@example.test']],'includes_samples'=>true,'contacts'=>[['email'=>'private@example.test']],'inbox'=>'private reply','draft'=>'private draft'];
$window=['start'=>'2026-09-17','end'=>'2026-10-16','compare'=>'previous','bots'=>'filtered','messages_mode'=>'all','messages'=>[],'segment'=>0,'secret'=>'private-window'];
$evidence=audienceAiEvidence($overview,$window);
$expect(!str_contains(json_encode($evidence),'private')&&!str_contains(json_encode($evidence),'secret'),'Analysis allowlist excludes PII, messages and unapproved window data');
$expect($evidence['facts'][0]['change']===20.0&&$evidence['facts'][4]['change']===null,'Comparison is calculated by the app and zero baseline is unavailable');
$analysis=audienceAiRequest(['mode'=>'analytics','operation'=>'analyze','prompt'=>'What changed?','request_id'=>$base['request_id']],'admin')+['evidence'=>$evidence];
$interpretation=['summary'=>'Engagement softened in the selected period.','observations'=>[['evidence_id'=>'click_rate','text'=>'Click rate declined relative to the comparison period.']],'recommendations'=>['Review the clarity of the primary call to action.']];
$decoded=audienceAiReply($raw($interpretation),$analysis);$expect($decoded['evidence']===$evidence,'Charts and facts retain original server provenance');
$reject(static fn()=>audienceAiReply($raw(array_replace($interpretation,['observations'=>[['evidence_id'=>'revenue','text'=>'Revenue rose.']]])),$analysis),'Invented evidence references are rejected');
$reject(static fn()=>audienceAiReply($raw(array_replace($interpretation,['summary'=>'You earned 999 dollars.'])),$analysis),'Unverified numeric prose is rejected');
$fact=$evidence['facts'][0];$supported=array_replace($interpretation,['observations'=>[['evidence_id'=>'accepted','text'=>'Sending volume was '.$fact['value'].'.']]]);$expect(audienceAiReply($raw($supported),$analysis)['observations'][0]['text']===$supported['observations'][0]['text'],'A numeric observation can quote its exact cited source');
$reject(static fn()=>audienceAiReply($raw(array_replace($interpretation,['observations'=>[['evidence_id'=>'click_rate','text'=>'Click rate was '.$fact['value'].'.']]])),$analysis),'A number from a different fact cannot support the cited observation');
$payload=audienceAiPayload($analysis);$expect($payload['think']===false&&$payload['options']['num_ctx']===8192&&$payload['options']['num_predict']<=1100,'Existing engine budgets remain bounded');
putenv('DNR_AI_COACH_URL=http://ai-coach-tunnel:11437');
$request['account']=currentAccountKey();$calls=0;
$result=audienceAiGenerate($request,microtime(true)+10,null,static function($url,$payload,$deadline,$cancelled,&$metrics)use(&$calls,$raw,$reply):array{$calls++;if($url!=='http://ai-coach-tunnel:11437')throw new RuntimeException('Unexpected destination');$metrics=['eval_count'=>42];return $raw($reply);});
$expect($calls===1&&($result['reason']??'')===''&&$result['telemetry']['model_calls']===1,'Generation reuses the configured transport exactly once');
$result=audienceAiGenerate(array_replace($request,['account'=>'other-account']),microtime(true)+10,null,static function()use(&$calls){$calls++;return [];});
$expect($calls===1&&$result['reason']==='unavailable','Cross-account job data never reaches inference');
$retired=$analysis+['account'=>currentAccountKey()];$retired['evidence']['window']['origin']='mailchimp';
$result=audienceAiGenerate($retired,microtime(true)+10,null,static function()use(&$calls){$calls++;return [];});
$expect($calls===1&&$result['reason']==='unavailable','Queued analysis from a removed source never reaches inference');
$result=audienceAiGenerate($request,microtime(true)+10,null,static fn()=>throw new AiCoachModelFailure('cancelled'));
$expect($result['reason']==='cancelled','Cancellation has an explicit native outcome');
putenv('DNR_AI_COACH_URL=https://user:password@example.test');
$result=audienceAiGenerate($request,microtime(true)+10,null,static function()use(&$calls){$calls++;return [];});
$expect($calls===1&&$result['reason']==='unavailable','Malformed configured endpoints are rejected without inference');
putenv('DNR_AI_COACH_URL');
echo "MessageMonkey AI validation and evidence tests passed ($checks checks).\n";
